create or replace view public.master_annual_report with (security_invoker=true) as select b.tenant_id,b.company_id,b.budget_year,b.salary_projection,b.other_planned,b.total_planned_expense,b.actual_expense,b.actual_income,b.planned_remaining,b.engineering_projected_revenue,b.exceeded_limits,b.warning_limits,b.budget_execution_percent,(b.actual_income-b.actual_expense)::numeric(14,2) actual_result,(b.engineering_projected_revenue-b.total_planned_expense)::numeric(14,2) projected_result from public.budget_dashboard_annual b;
create or replace view public.master_engineering_monthly_report with (security_invoker=true) as with m as (select tenant_id,company_id,competence,count(distinct work_id)::integer works_measured,count(distinct contract_id)::integer contracts_measured,count(*)::integer measurements,coalesce(sum(gross_amount),0)::numeric(14,2) gross_measured,coalesce(sum(retained_amount),0)::numeric(14,2) retained_amount,coalesce(sum(net_amount),0)::numeric(14,2) net_measured from public.engineering_measurement_monthly_report group by tenant_id,company_id,competence),p as (select tenant_id,company_id,competence,count(distinct work_id)::integer works_with_production,count(distinct employee_id)::integer employees_with_production,coalesce(sum(executed_quantity),0)::numeric executed_quantity,coalesce(sum(production_value),0)::numeric(14,2) production_value from public.engineering_employee_production_summary group by tenant_id,company_id,competence) select coalesce(m.tenant_id,p.tenant_id) tenant_id,coalesce(m.company_id,p.company_id) company_id,coalesce(m.competence,p.competence) competence,coalesce(m.works_measured,0) works_measured,coalesce(m.contracts_measured,0) contracts_measured,coalesce(m.measurements,0) measurements,coalesce(m.gross_measured,0)::numeric(14,2) gross_measured,coalesce(m.retained_amount,0)::numeric(14,2) retained_amount,coalesce(m.net_measured,0)::numeric(14,2) net_measured,coalesce(p.works_with_production,0) works_with_production,coalesce(p.employees_with_production,0) employees_with_production,coalesce(p.executed_quantity,0) executed_quantity,coalesce(p.production_value,0)::numeric(14,2) production_value from m full join p on p.tenant_id=m.tenant_id and p.company_id=m.company_id and p.competence=m.competence;
create or replace view public.master_report_catalog with (security_invoker=true) as select d.tenant_id,d.company_id,'executive'::text report_group,'company_dashboard'::text report_key,d.company_name report_name,current_date reference_date from public.master_company_dashboard d union all select m.tenant_id,m.company_id,'budget'::text,'monthly_budget','Previsto x Realizado mensal',m.competence_month from public.master_company_monthly_dashboard m union all select a.tenant_id,a.company_id,'budget'::text,'annual_budget','Previsto x Realizado anual',a.budget_year from public.master_annual_report a union all select e.tenant_id,e.company_id,'engineering'::text,'engineering_monthly','Engenharia mensal',e.competence from public.master_engineering_monthly_report e;
comment on view public.master_annual_report is 'Annual planned versus actual report by company.';
comment on view public.master_engineering_monthly_report is 'Monthly engineering measurement and production consolidated report.';
comment on view public.master_report_catalog is 'Master report catalog for dashboard/report navigation.';